    cpu_percent = psutil.cpu_percent(interval=0.1)
    memory = psutil.virtual_memory()

    disk_root = psutil.disk_usage('/')
    disk_data = None
    try:
        disk_data = psutil.disk_usage('/data')
    except Exception:
        pass

    boot_time = psutil.boot_time()
    uptime_seconds = int(time.time() - boot_time)

    return {
