        "disk_root": {
            "total_gb": round(disk_root.total / (1024**3), 2),
            "used_gb": round(disk_root.used / (1024**3), 2),
            "free_gb": round(disk_root.free / (1024**3), 2),
            "percent": disk_root.percent
