import asyncio
from fastapi import APIRouter, Request, BackgroundTasks
from fastapi.responses import HTMLResponse, StreamingResponse, JSONResponse
from fastapi.templating import Jinja2Templates
from pathlib import Path
import json

from app.config import load_config
from app.utils.system_health import get_system_health, check_webdav_latency
from app.utils.logger import memory_handler, logger

router = APIRouter()
templates = Jinja2Templates(directory=str(Path(__file__).parent / "templates"))

@router.get("/", response_class=HTMLResponse)
async def dashboard(request: Request):
    config = load_config()
    health = get_system_health()
    return templates.TemplateResponse(
        request=request,
        name="dashboard.html",
        context={
            "config": config,
            "health": health
        }
    )

@router.get("/api/health")
async def api_health():
    config = load_config()
    health = get_system_health()

    webdav_status = {}
    if config.webdav_source.get("url"):
        webdav_status["source"] = check_webdav_latency(
            config.webdav_source["url"], 
            config.webdav_source.get("username", ""), 
            config.webdav_source.get("password", "")
        )

    for k, dest in config.webdav_destinations.items():
        if dest.get("url"):
            webdav_status[k] = check_webdav_latency(
                dest["url"], 
                dest.get("username", ""), 
                dest.get("password", "")
            )

    health["webdav_servers"] = webdav_status
    return JSONResponse(health)

@router.get("/api/logs")
async def get_logs():
    recent = memory_handler.get_recent_logs(limit=100)
    return JSONResponse({"logs": recent})

@router.get("/api/logs/stream")
async def stream_logs():
    async def log_generator():
        last_idx = 0
        while True:
            logs = memory_handler.get_recent_logs(limit=200)
            if len(logs) > last_idx:
                new_entries = logs[last_idx:]
                last_idx = len(logs)
                for entry in new_entries:
                    yield f"data: {json.dumps(entry)}\n\n"
            await asyncio.sleep(1)

    return StreamingResponse(log_generator(), media_type="text/event-stream")

@router.get("/api/catalog")
async def get_catalog_cards():
    config = load_config()
    cards = []
    if config.catalog_dir.exists():
        for f in config.catalog_dir.glob("*.md"):
            cards.append({
                "filename": f.name,
                "title": f.stem.replace('_', ' ').title(),
                "modified": f.stat().st_mtime
            })
    return JSONResponse({"cards": sorted(cards, key=lambda x: x["modified"], reverse=True)})

@router.post("/api/scan/trigger")
async def trigger_scan(background_tasks: BackgroundTasks):
    from app.core.monitor import MonitorOrchestrator
    config = load_config()
    orchestrator = MonitorOrchestrator(config)

    background_tasks.add_task(orchestrator.run_cycle)
    logger.info("Manual WebDAV scan triggered from web interface.")
    return JSONResponse({"status": "scan_started", "message": "Manual WebDAV scan initiated."})
EOF

