        const grid = document.getElementById('catalogCardsGrid');
        grid.innerHTML = '';

        if (data.cards.length === 0) {
            grid.innerHTML = '<p class="subtext">No catalog cards generated yet. Deposit books into WebDAV incoming folder to auto-generate cards.</p>';
            return;
        }

        for (const card of data.cards) {
            grid.innerHTML += `
                <div class="card catalog-card">
                    <h3>📘 ${card.title}</h3>
                    <p class="subtext">File: ${card.filename}</p>
                    <a href="/data/book_processor/catalog/${card.filename}" target="_blank" class="btn btn-sm btn-outline">View Card Markdown</a>
                </div>
            `;
        }
    } catch (e) {
        console.error('Catalog load error:', e);
    }
}

async function triggerScan() {
    const btn = document.getElementById('scanBtn');
    btn.disabled = true;
    btn.innerText = "⏳ Scanning...";
    try {
        const res = await fetch('/api/scan/trigger', { method: 'POST' });
        const data = await res.json();
        alert(data.message);
    } catch (e) {
        alert("Scan trigger failed: " + e);
    } finally {
        btn.disabled = false;
        btn.innerText = "🔄 Run WebDAV Scan";
    }
}

